using System.Reflection;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace Afterline;

internal static class CanaryBuildHistory
{
    // Generated by the Windows workflow from actual successful Canary runs.
    // Reading the embedded resource performs no network request at runtime.
    public static IReadOnlyList<ChangelogEntry> Entries { get; } = Load();

    internal static void ValidatePackagedBuild()
    {
        string version = (Assembly.GetEntryAssembly() ?? typeof(CanaryBuildHistory).Assembly)
            .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? string.Empty;
        Match match = Regex.Match(version, @"-canary\.(?<build>\d+)", RegexOptions.IgnoreCase);
        if (match.Success && int.TryParse(match.Groups["build"].Value, out int build) &&
            !Entries.Any(entry => entry.CanaryBuild == build))
            throw new InvalidDataException($"Canary #{build} is missing its own changelog entry.");
    }

    private static IReadOnlyList<ChangelogEntry> Load()
    {
        try
        {
            Assembly assembly = typeof(CanaryBuildHistory).Assembly;
            using Stream? stream = assembly.GetManifestResourceStream("Afterline.CanaryBuildHistory.json");
            if (stream is null) return Array.Empty<ChangelogEntry>();
            using var document = JsonDocument.Parse(stream);
            return document.RootElement.EnumerateArray()
                .Select(item => new ChangelogEntry(
                    item.GetProperty("version").GetString() ?? "0.7.0",
                    item.GetProperty("date").GetString() ?? "Date unavailable",
                    new[] { item.GetProperty("summary").GetString() ?? "Build notes unavailable." },
                    ChangelogChannel.Canary,
                    item.GetProperty("build").GetInt32()))
                .Where(item => item.CanaryBuild > 0)
                .OrderByDescending(item => item.CanaryBuild)
                .ToArray();
        }
        catch (Exception)
        {
            return Array.Empty<ChangelogEntry>();
        }
    }
}
